P.wwf = {"short": "WWF", "name": "World Wrestling Federation", "home": "Stamford, CT", "c": "var(--wwf)", "status": "Eight shows into July and $1.58 million in the door. Regina was the low point of the Canadian swing, Winnipeg the best card of the tour, and Sgt. Slaughter goes into WrestleFest with a DQ win over the Warrior. WrestleFest '91 at Busch Stadium is Sunday; SummerSlam at Madison Square Garden is Sunday 8/25.", "stat": ["$1,575,280", "July gates, 8 shows"], "titles": [["WWF Championship", "Hulk Hogan", "Defends vs. Sgt. Slaughter at WrestleFest 7/14, Duggan as enforcer."], ["Intercontinental", "Mr. Perfect", "Retained vs. Davey Boy Smith 7/5 and Tito Santana 7/8. Vs. Greg Valentine at WrestleFest."], ["World Tag Team", "The Nasty Boys", "Retained vs. the Rockers by DQ (7/1) and LOD by count-out (7/10). Vs. the Rockers at WrestleFest."], ["Million Dollar Championship", "Ted DiBiase", "Vs. Virgil at WrestleFest."]], "factions": [["Jimmy Hart", "IRS, Ted DiBiase, Dino Bravo, the Mountie and Earthquake."], ["Bobby Heenan", "Mr. Perfect, Haku and the Barbarian."], ["Harvey Wippleman", "Sid Justice and Warlord."], ["Mr. Fuji", "The Berzerker and the Orient Express."], ["Paul Bearer", "The Undertaker."], ["Gen. Adnan", "Sgt. Slaughter."], ["Coach", "The Beverly Brothers."], ["Miss Elizabeth", "Randy Savage, who is retired and working non-wrestling segments."]], "stories": [["Hogan vs. Slaughter", "WrestleFest '91 main event, Busch Stadium, 7/14. Hacksaw Jim Duggan is Hogan's special enforcer. Twelve matches underneath."], ["Sid Is Watching", "Sid saved Hogan at the Vancouver taping and stared at the belt. Wippleman jawed at Hogan in Calgary. In Saskatoon, Sid sat at ringside for the whole Hogan–Warlord main event."], ["The Edmonton Injuries", "Earthquake (neck), Greg Valentine (neck) and Bushwhacker Butch (elbow) all went down on 7/9. Typhoon replaces Earthquake against Jake at WrestleFest."], ["Jake Hesitates", "Jake Roberts no-showed MSG, beat Earthquake twice, and then, in Edmonton, waited a beat too long before saving the Warrior."], ["Nastys Survive", "The Nasty Boys kept the tag titles on a count-out against LOD in Saskatoon. Paul Ellering showed up in LOD's corner. LOD hit the Doomsday Device on Knobbs after."], ["Owen Steals the Show", "Owen Hart beat Rick Martel in Calgary (***1/2) on the best-rated WWF card of July. 13,000 paid $260,000."], ["Garden Gold, Road Rust", "MSG drew $543,200 for a *1/2 card. Warrior beat the Undertaker three nights running, and the ratings kept falling."], ["Cuffed", "The Mountie handcuffed Big Boss Man to the ropes in Calgary. Boss Man is at ringside for Mountie vs. Tito at WrestleFest."], ["Virgil Strikes Back", "Virgil cut IRS off in Calgary and pinned him in Edmonton. He gets DiBiase one on one at WrestleFest."], ["The SWS Experiment", "Tenryu & Kitao had the co-match of the night in Edmonton (***1/4). SATO went *** in Calgary, then lost by DQ in 42 seconds in Saskatoon."], ["The Bulldog's Two Masters", "Davey Boy Smith is finishing the All Japan tour and won't be back until about 7/29. The office isn't happy."], ["Steamboat Down", "Ricky Steamboat tore his right ACL against Skinner in Des Moines on 7/5."]], "desk": ["WrestleFest '91 is booked; results to come.", "Jimmy Snuka no-showed Regina 7/11 (missed the drive from Saskatoon). He made Winnipeg.", "Unplanned thread: Road Warrior Hawk ran in on Sgt. Slaughter in Regina. LOD vs. Slaughter?", "Owen Hart has gone **3/4 or better in all four shows this week. He replaces Valentine as IC challenger at WrestleFest.", "Sid Justice: -***1/4 and -** in two of his three loop matches. Kitao singles and Crush aren't working either.", "Steamboat: roster export says 12 more cards; the earlier estimate was ~10 months. Needs a ruling.", "Paul Ellering appeared with LOD in Saskatoon. In this world he's with Andre in the USWA. Explain or drop.", "Davey Boy Smith unavailable until about 7/29. Keep his Japan schedule off WWF TV.", "Keep Warlord out of singles main events (DUD vs. Hogan 7/10, -*1/2 vs. Virgil 7/5).", "Beefcake has rated -***1/4 twice (Crush, Sid). Keep him out of singles.", "SummerSlam '91: Sunday 8/25, Madison Square Garden, head to head with WCW at the Omni."], "roster": [["Ax", "Demolition"], ["Beau Beverly", "Beverly Brothers · w/ Coach"], ["Big Boss Man", "vs. the Mountie"], ["Blake Beverly", "Beverly Brothers · w/ Coach"], ["Brian Knobbs", "Tag Champion · Nasty Boys"], ["Brutus Beefcake", ""], ["Bushwhacker Butch", "INJ:Elbow (7/9), ~1 card"], ["Bushwhacker Luke", "Bushwhackers"], ["Crush", "Demolition"], ["Davey Boy Smith", "Unavailable until ~7/29"], ["Dino Bravo", "w/ Jimmy Hart"], ["Earthquake", "INJ:Neck (7/9), ~5 cards, back ~7/18 · w/ Jimmy Hart"], ["Genichiro Tenryu", "SWS"], ["Greg Valentine", "INJ:Neck (7/9), back for WrestleFest · vs. Perfect"], ["Haku", "w/ Heenan"], ["Hercules", "Power & Glory"], ["Hulk Hogan", "WWF Champion"], ["Irwin R. Schyster", "Money Inc. · w/ Jimmy Hart"], ["Jake Roberts", "Hesitated before saving Warrior 7/9"], ["Jerry Sags", "Tag Champion · Nasty Boys"], ["Jim Duggan", ""], ["Jimmy Snuka", ""], ["Kato", "Orient Express · w/ Fuji"], ["Koji Kitao", "SWS"], ["Koko B. Ware", "High Energy"], ["Marty Jannetty", "Rockers"], ["Mr. Perfect", "Intercontinental Champion · w/ Heenan"], ["Owen Hart", "High Energy · vs. Beverlys at WrestleFest"], ["Paul Roma", "Power & Glory"], ["Randy Savage", "Retired · w/ Elizabeth · Superstars commentary"], ["Rick Martel", ""], ["Road Warrior Animal", "Legion of Doom"], ["Road Warrior Hawk", "Legion of Doom"], ["SATO", "SWS"], ["Sgt. Slaughter", "w/ Gen. Adnan"], ["Shane Douglas", ""], ["Shawn Michaels", "Rockers"], ["Sid Justice", "w/ Harvey Wippleman · watching Hogan"], ["Skinner", ""], ["Smash", "Demolition"], ["Tanaka", "Orient Express · w/ Fuji"], ["Ted DiBiase", "Money Inc. · w/ Jimmy Hart"], ["The Barbarian", "w/ Heenan"], ["The Berzerker", "w/ Fuji"], ["The Mountie", "w/ Jimmy Hart"], ["The Ultimate Warrior", ""], ["The Undertaker", "w/ Paul Bearer"], ["Tito Santana", ""], ["Typhoon", "Natural Disasters · replaces Earthquake at WrestleFest"], ["Virgil", "vs. DiBiase · pinned IRS 7/9"], ["Warlord", "w/ Harvey Wippleman"], ["Ricky Steamboat", "INJ:Torn right ACL (7/5). Roster export: 12 more cards"], ["Jimmy Hart", "Manager"], ["Bobby Heenan", "Manager"], ["Harvey Wippleman", "Manager"], ["Mr. Fuji", "Manager"], ["Paul Bearer", "Manager"], ["Gen. Adnan", "Manager"], ["Coach", "Manager"], ["Miss Elizabeth", "Manager"]], "departures": [["Big Bubba Rogers", "No longer with the WWF (7/10)."]], "asOf": "1991-07-12"};

